import numpy as np
from scipy.optimize import least_squares
y=dA_dt
def run(S,p0,n=14):
    def F(p):
        return (S(p[:-1],t,A)-p[-1]*t**2*A**1.5)-y
    best=None
    np.random.seed(7)
    for s in range(n):
        pp=np.array(p0+[0.0129],float)*(1+0.25*np.random.randn(len(p0)+1)) if s else np.array(p0+[0.0129],float)
        try:
            with np.errstate(all='ignore'):
                r=least_squares(F,pp,max_nfev=4000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return np.mean(best.fun**2)/np.var(y), np.round(best.x,5)
